export async function findCurrentMember(
  orgId: OrgId,
  userId: UserId,
): Promise<Member | null> {
  const member = await findMember(orgId, userId);
  return member?.status === "active" ? member : null;
}

/** The subset of `userIds` that are current members of `orgId`, in input order. */
export async function filterCurrentMembers(
  orgId: OrgId,
  userIds: readonly UserId[],
): Promise<readonly UserId[]> {
  if (userIds.length === 0) return [];

  const rows = getDb()
    .select({ userId: members.userId })
    .from(members)
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        inArray(members.userId, [...userIds]),
        eq(members.status, "active"),
        liveMemberPredicate(),
      ),
    )
    .all();

  const current = new Set(rows.map((row) => row.userId));
  return userIds.filter((userId) => current.has(userId));
}

