/**
 * Union of the ids the client already resolved (optimistic UI) and the ones
 * parsed out of the body server-side. Only current members survive either way:
 * a departed member or a stranger is dropped without error, so it is neither
 * stored nor notified.
 */
async function resolveMentionedUsers(
  orgId: OrgId,
  body: string,
  clientProvided: readonly UserId[],
): Promise<readonly UserId[]> {
  const members = await memberRepo.listMembers({
    orgId,
    status: "active",
    limit: MENTION_LOOKUP_LIMIT,
    cursor: null,
  });

  const resolved = resolveMentions(body, members.items);
  const provided = await memberRepo.filterCurrentMembers(orgId, clientProvided);

  return [...new Set([...resolved, ...provided])];
}

