import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { subscribe } from "@/lib/event-bus";
import { TenantScopeError } from "@/lib/tenant";
import { getDb, issueLabels } from "@/server/db";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as labelService from "@/server/services/label-service";
import * as projectService from "@/server/services/project-service";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { CommentId, IssueId, LabelId, UserId } from "@/types/common";
import type { Issue } from "@/types/issue";
import type { Comment } from "@/types/comment";

let cleanup: () => void;
let north: Tenant;
let acme: Tenant;
let departed: Tenant;
let acmeIssue: Issue;
let acmeComment: Comment;
let northIssue: Issue;
let northLabel: { id: LabelId };
let acmeLabel: { id: LabelId };
let outsider: { id: UserId };
let events: string[] = [];

const offs: Array<() => void> = [];

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  north = await createTenant("refnorth");
  acme = await createTenant("refacme");
  departed = await createTenant("refdeparted");

  outsider = await userRepo.insertUser({
    email: "stranger@refnorth.test",
    name: "Stranger",
    passwordHash: "seed",
  });

  acmeIssue = await issueService.createIssue(
    acme.actors.member,
    issueInput(acme.org.id, acme.project.id, { title: "Acme issue" }),
  );
  acmeComment = await commentService.createComment(acme.actors.member, {
    orgId: acme.org.id,
    issueId: acmeIssue.id,
    body: "acme comment",
    parentId: null,
    mentionedUserIds: [],
  });

  northIssue = await issueService.createIssue(
    north.actors.member,
    issueInput(north.org.id, north.project.id, { title: "North issue" }),
  );

  northLabel = await labelService.createLabel(north.actors.owner, {
    orgId: north.org.id,
    name: "north-label",
    color: "#111111",
    description: null,
  });
  acmeLabel = await labelService.createLabel(acme.actors.owner, {
    orgId: acme.org.id,
    name: "acme-label",
    color: "#222222",
    description: null,
  });

  for (const name of ["issue.created", "issue.assigned", "issue.updated", "comment.created", "project.created", "project.updated"]) {
    offs.push(subscribe(name as "issue.created", () => { events.push(name); }));
  }
});

afterAll(() => {
  for (const off of offs) off();
  cleanup();
});

function quietly<T>(fn: () => Promise<T>) {
  events = [];
  return fn();
}

describe("assignees and leads must be current members", () => {
  it("refuses assigning a stranger on create, and nothing is created or announced", async () => {
    const before = await issueRepo.countIssues(north.org.id, north.project.id);
    await expect(
      quietly(() =>
        issueService.createIssue(
          north.actors.member,
          issueInput(north.org.id, north.project.id, { title: "Stranger assignee", assigneeId: outsider.id }),
        ),
      ),
    ).rejects.toBeInstanceOf(NotFoundError);
    expect(await issueRepo.countIssues(north.org.id, north.project.id)).toBe(before);
    expect(events).toEqual([]);
  });

  it("refuses assigning a stranger on assign, and the issue is unchanged", async () => {
    await expect(
      quietly(() =>
        issueService.assignIssue(north.actors.member, {
          orgId: north.org.id,
          issueId: northIssue.id,
          assigneeId: outsider.id,
        }),
      ),
    ).rejects.toBeInstanceOf(NotFoundError);
    const reread = await issueRepo.findIssueById(north.org.id, northIssue.id);
    expect(reread?.assigneeId).toBeNull();
    expect(events).toEqual([]);
  });

  it("refuses a member of another workspace as assignee", async () => {
    await expect(
      issueService.assignIssue(north.actors.member, {
        orgId: north.org.id,
        issueId: northIssue.id,
        assigneeId: acme.userIds.member,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

