      orgId: north.org.id,
      issueId: northIssue.id,
      body: "reply",
      parentId: top.id,
      mentionedUserIds: [],
    });
    expect(reply.parentId).toBe(top.id);
    const thread = await commentRepo.listThread(north.org.id, northIssue.id);
    const node = thread.find((item) => item.comment.id === top.id);
    expect(node?.replies.map((r) => r.id)).toContain(reply.id);
  });

  it("refuses a reply to a comment on another issue, and posts nothing", async () => {
    const otherIssue = await issueService.createIssue(
      north.actors.member,
      issueInput(north.org.id, north.project.id, { title: "Other issue" }),
    );
    const top = await commentService.createComment(north.actors.member, {
      orgId: north.org.id,
      issueId: northIssue.id,
      body: "elsewhere",
      parentId: null,
      mentionedUserIds: [],
    });
    const before = await commentRepo.countComments(north.org.id, otherIssue.id);
    await expect(
      quietly(() =>
        commentService.createComment(north.actors.member, {
          orgId: north.org.id,
          issueId: otherIssue.id,
          body: "wrong issue",
          parentId: top.id,
          mentionedUserIds: [],
        }),
      ),
    ).rejects.toBeInstanceOf(NotFoundError);
    expect(await commentRepo.countComments(north.org.id, otherIssue.id)).toBe(before);
    expect(events).toEqual([]);
  });

  it("refuses a reply to a deleted comment as not found", async () => {
    const top = await commentService.createComment(north.actors.member, {
      orgId: north.org.id,
      issueId: northIssue.id,
      body: "to be deleted",
      parentId: null,
      mentionedUserIds: [],
    });
    await commentService.deleteComment(north.actors.member, {
      orgId: north.org.id,
      commentId: top.id,
    });
    await expect(
      commentService.createComment(north.actors.member, {
        orgId: north.org.id,
        issueId: northIssue.id,
        body: "reply to deleted",
        parentId: top.id,
        mentionedUserIds: [],
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("refuses a reply to a reply as not found", async () => {
    const top = await commentService.createComment(north.actors.member, {
      orgId: north.org.id,
      issueId: northIssue.id,
      body: "root for nested",
      parentId: null,
