      body: "first reply",
      parentId: top.id,
      mentionedUserIds: [],
    });
    await expect(
      commentService.createComment(north.actors.member, {
        orgId: north.org.id,
        issueId: northIssue.id,
        body: "reply to reply",
        parentId: reply.id,
        mentionedUserIds: [],
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("refuses a comment from another workspace as a tenant violation", async () => {
    await expect(
