});

describe("mentions only ever reach current members", () => {
  it("drops a stranger supplied by the composer and notifies nobody for them", async () => {
    const received: Array<{ mentionedUserIds: readonly string[] }> = [];
    const off = subscribe("comment.created", (payload) => {
      received.push(payload);
    });
