  it("refuses a missing parent as not found", async () => {
    await expect(
      issueService.createIssue(north.actors.member, {
        ...issueInput(north.org.id, north.project.id, { title: "Ghost parent" }),
        parentId: "ISS_MISSING" as IssueId,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("accepts a live parent in the same project", async () => {
    const parent = await issueService.createIssue(
      north.actors.member,
