/**
 * Creates an issue after four gates: tenant scope, a live project, the
 * `issue:create` permission and the references the issue carries (see
 * `assertIssueReferences`), then the plan's per-project issue quota. Only then
 * is a number allocated and `issue.created` published — everything reactive
 * (notifications, search, webhooks, the audit log) hangs off that.
 */
export async function createIssue(
  actor: Actor,
  input: CreateIssueInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  assertReferenceInScope(
    actor,
    await projectRepo.findProjectOwnerOrgId(input.projectId),
    "Project",
    input.projectId,
  );
  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  await assertIssueReferences(actor, input);

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  const used = await issueRepo.countIssues(input.orgId, input.projectId);
  if (wouldExceedLimit(org.plan, "issuesPerProject", used)) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${project.key}`,
    );
  }

  const number = await issueRepo.nextIssueNumber(input.orgId, input.projectId);
  const issue = await issueRepo.insertIssue(input, actor.userId, number);

  await emit("issue.created", {
    ...actorEnvelope(actor),
    issueId: issue.id,
    projectId: issue.projectId,
    title: issue.title,
    assigneeId: issue.assigneeId,
    priority: issue.priority,
  });

  return issue;
}

/**
 * Everything a new issue points at must be usable from this workspace: the
 * assignee is a current member, the parent is a live issue of the same project,
 * and every label is one of this workspace's own.
 */
async function assertIssueReferences(
  actor: Actor,
  input: CreateIssueInput,
): Promise<void> {
  if (input.assigneeId !== null) {
    await assertCurrentMember(input.orgId, input.assigneeId);
  }
  if (input.parentId !== null) {
    await assertParentIssue(actor, input.projectId, input.parentId);
  }
  await assertLabelsInScope(actor, input.labelIds);
}

/**
 * A parent must be a live issue of the same project. One that is archived, sits
 * in another project or does not exist is not found; one in another workspace
 * is refused as a tenant violation.
 */
async function assertParentIssue(
  actor: Actor,
  projectId: ProjectId,
  parentId: IssueId,
): Promise<void> {
  assertReferenceInScope(
    actor,
    await issueRepo.findIssueOwnerOrgId(parentId),
    "Issue",
    parentId,
  );
  const parent = requireFound(
    await issueRepo.findIssueById(actor.orgId, parentId),
    "Issue",
    parentId,
  );
  if (!isLive(parent) || parent.projectId !== projectId) {
    throw new NotFoundError("Issue", parentId);
  }
}

/** Each label must be one of this workspace's own labels. */
async function assertLabelsInScope(
  actor: Actor,
  labelIds: readonly LabelId[],
